-- Cronograma editável pelo painel e solicitações de códigos das mídias.

-- ------------------------------------------------------------------ cronograma
CREATE TABLE IF NOT EXISTS public.schedule_weeks (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  start_date date NOT NULL UNIQUE,
  periodo text NOT NULL DEFAULT '',
  tema text NOT NULL DEFAULT '',
  -- { "Categoria": ["evento", ...] } na ordem em que aparecem
  eventos jsonb NOT NULL DEFAULT '{}'::jsonb,
  -- eventos da Cronograma Econômica da semana
  economica jsonb NOT NULL DEFAULT '[]'::jsonb,
  updated_by uuid REFERENCES auth.users(id) ON DELETE SET NULL DEFAULT auth.uid(),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.schedule_weeks TO authenticated;
GRANT ALL ON public.schedule_weeks TO service_role;
ALTER TABLE public.schedule_weeks ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Team reads schedule" ON public.schedule_weeks;
CREATE POLICY "Team reads schedule" ON public.schedule_weeks
  FOR SELECT TO authenticated USING (true);

DROP POLICY IF EXISTS "Admins insert schedule" ON public.schedule_weeks;
CREATE POLICY "Admins insert schedule" ON public.schedule_weeks
  FOR INSERT TO authenticated
  WITH CHECK (private.has_role(auth.uid(), 'admin'::public.app_role) OR private.has_role(auth.uid(), 'super_admin'::public.app_role));

DROP POLICY IF EXISTS "Admins update schedule" ON public.schedule_weeks;
CREATE POLICY "Admins update schedule" ON public.schedule_weeks
  FOR UPDATE TO authenticated
  USING (private.has_role(auth.uid(), 'admin'::public.app_role) OR private.has_role(auth.uid(), 'super_admin'::public.app_role));

DROP POLICY IF EXISTS "Admins delete schedule" ON public.schedule_weeks;
CREATE POLICY "Admins delete schedule" ON public.schedule_weeks
  FOR DELETE TO authenticated
  USING (private.has_role(auth.uid(), 'admin'::public.app_role) OR private.has_role(auth.uid(), 'super_admin'::public.app_role));

DROP TRIGGER IF EXISTS update_schedule_weeks_updated_at ON public.schedule_weeks;
CREATE TRIGGER update_schedule_weeks_updated_at
  BEFORE UPDATE ON public.schedule_weeks
  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();

