-- ------------------------------------------------------------------ solicitações de códigos
CREATE TABLE IF NOT EXISTS public.code_requests (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  requested_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE DEFAULT auth.uid(),
  requester_email text NOT NULL DEFAULT '',
  channel text NOT NULL DEFAULT '',
  purpose text NOT NULL,
  quantity integer NOT NULL DEFAULT 1 CHECK (quantity > 0),
  reward text NOT NULL DEFAULT '',
  servers text NOT NULL DEFAULT '',
  needed_by date,
  notes text NOT NULL DEFAULT '',
  status text NOT NULL DEFAULT 'pendente' CHECK (status IN ('pendente', 'aprovado', 'entregue', 'recusado')),
  response text NOT NULL DEFAULT '',
  handled_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  handled_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS code_requests_requested_by_idx ON public.code_requests (requested_by, created_at DESC);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.code_requests TO authenticated;
GRANT ALL ON public.code_requests TO service_role;
ALTER TABLE public.code_requests ENABLE ROW LEVEL SECURITY;

-- Papéis comparados como texto: o valor 'midia' é criado na migração anterior.
CREATE OR REPLACE FUNCTION private.role_in(_user uuid, _roles text[])
RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public
AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user AND role::text = ANY (_roles)) $$;
REVOKE ALL ON FUNCTION private.role_in(uuid, text[]) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION private.role_in(uuid, text[]) TO authenticated, service_role;

DROP POLICY IF EXISTS "Requesters and admins read code requests" ON public.code_requests;
CREATE POLICY "Requesters and admins read code requests" ON public.code_requests
  FOR SELECT TO authenticated
  USING (requested_by = auth.uid() OR private.role_in(auth.uid(), ARRAY['admin', 'super_admin']));

DROP POLICY IF EXISTS "Media and admins create code requests" ON public.code_requests;
CREATE POLICY "Media and admins create code requests" ON public.code_requests
  FOR INSERT TO authenticated
  WITH CHECK (requested_by = auth.uid() AND status = 'pendente' AND private.role_in(auth.uid(), ARRAY['midia', 'admin', 'super_admin']));

DROP POLICY IF EXISTS "Admins update code requests" ON public.code_requests;
CREATE POLICY "Admins update code requests" ON public.code_requests
  FOR UPDATE TO authenticated
  USING (private.role_in(auth.uid(), ARRAY['admin', 'super_admin']));

DROP POLICY IF EXISTS "Requesters cancel pending, admins delete code requests" ON public.code_requests;
CREATE POLICY "Requesters cancel pending, admins delete code requests" ON public.code_requests
  FOR DELETE TO authenticated
  USING ((requested_by = auth.uid() AND status = 'pendente') OR private.role_in(auth.uid(), ARRAY['admin', 'super_admin']));

DROP TRIGGER IF EXISTS update_code_requests_updated_at ON public.code_requests;
CREATE TRIGGER update_code_requests_updated_at
  BEFORE UPDATE ON public.code_requests
  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
